payload.template:
module mux2 (
  input  logic a,     // passed through when sel is 0
  input  logic b,     // passed through when sel is 1
  input  logic sel,   // which one
  output logic y      // the result
);

  // ---- your code goes here ----------------------------------------
  //
  // Drive y from a, b and sel: y is a when sel is 0, and b when sel
  // is 1. One line is enough.
  //
  // Combinational, so: a continuous "assign", or an always_comb block.
  // Not always_ff — there is no clock in this module.

  assign y = 1'b0;   // <- replace this

  // ------------------------------------------------------------------

endmodule

payload.testbench:
`timescale 1ns/1ps
// The sample testbench. Run uses this one, and you can read all of
// it. Submit uses a different one that drives these eight rows and a
// few more besides.
//
// It walks the whole truth table: three one-bit inputs is eight
// combinations, and every one of them is checked.
module tb;
  logic a, b, sel, y;

  mux2 dut (.a(a), .b(b), .sel(sel), .y(y));

  // What the answer should be, written out as the specification rather
  // than as a second implementation: y follows a when sel is 0.
  function automatic logic expected(logic xa, logic xb, logic xsel);
    return xsel ? xb : xa;
  endfunction

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // Row by row, 10 ns apart so each one is a clear step in the
    // waveform rather than a spike.
    for (int i = 0; i < 8; i++) begin
      {sel, a, b} = i[2:0];
      #10;
      $display("CHECK row%0d_sel%0b_a%0b_b%0b %0b %0b AT %0d",
               i, sel, a, b, expected(a, b, sel), y, $time);
    end

    #10;
    $display("DONE 8");
    $finish;
  end
endmodule
